// C program for the function called parse_number_string
// Contains target function implementation and dependency signatures

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Target function implementation
int parse_number_string(const char *input_str, uint8_t *out_int, uint8_t max_len)
{
    if (input_str == NULL || out_int == NULL || max_len == 0)
    {
        return -1;
    }

    long L = strlen(input_str);
    if (L == 0 || L > max_len)
    {
        return -1;
    }

    /* Initialize output array to zero */
    memset(out_int, 0, max_len);

    for (int i = 0; i < L; i++)
    {
        if (input_str[i] < '0' || input_str[i] > '9')
        {
            return -1;  /* Invalid character */
        }
        out_int[L - i - 1] = input_str[i] - '0';
    }

    return 0;
}

